def floyd(n, edges):
    """Floyd-Warshall: 返回 dis 距离矩阵 (可处理负权, 不含负环)。
    edges: [(u,v,w),...] 0-indexed"""
    INF = float('inf')
    dis = [[INF] * n for _ in range(n)]
    for i in range(n):
        dis[i][i] = 0
    for u, v, w in edges:
        dis[u][v] = min(dis[u][v], w)
    for k in range(n):
        for i in range(n):
            if dis[i][k] == INF:
                continue
            ik = dis[i][k]
            for j in range(n):
                if dis[k][j] == INF:
                    continue
                nd = ik + dis[k][j]
                if nd < dis[i][j]:
                    dis[i][j] = nd
    return dis


def floyd_has_neg_cycle(n, edges):
    """检测负环: Floyd 结束后存在 dis[i][i]<0"""
    dis = floyd(n, edges)
    for i in range(n):
        if dis[i][i] < 0:
            return True
    return False


def floyd_path(n, edges, s, t):
    """Floyd + 路径重建: 返回 (dist, path 节点列表); 不可达返回 (inf, [])"""
    INF = float('inf')
    dis = [[INF] * n for _ in range(n)]
    nxt = [[-1] * n for _ in range(n)]
    for i in range(n):
        dis[i][i] = 0
    for u, v, w in edges:
        if w < dis[u][v]:
            dis[u][v] = w
            nxt[u][v] = v
    for k in range(n):
        for i in range(n):
            if dis[i][k] == INF:
                continue
            for j in range(n):
                if dis[k][j] == INF:
                    continue
                nd = dis[i][k] + dis[k][j]
                if nd < dis[i][j]:
                    dis[i][j] = nd
                    nxt[i][j] = nxt[i][k]
    if dis[s][t] == INF:
        return INF, []
    path = []
    cur = s
    while cur != -1:
        path.append(cur)
        if cur == t:
            break
        cur = nxt[cur][t]
    return dis[s][t], path


if __name__ == "__main__":

    def dijkstra_all(adj, n):
        import heapq
        out = []
        for s in range(n):
            dis = [float('inf')] * n
            dis[s] = 0
            pq = [(0, s)]
            while pq:
                d, u = heapq.heappop(pq)
                if d > dis[u]:
                    continue
                for v, w in adj[u]:
                    if d + w < dis[v]:
                        dis[v] = d + w
                        heapq.heappush(pq, (dis[v], v))
            out.append(dis)
        return out

    import random
    random.seed(11)
    for _ in range(150):
        n = random.randint(1, 7)
        edges = []
        adj = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j and random.random() < 0.35:
                    w = random.randint(1, 8)
                    edges.append((i, j, w))
                    adj[i].append((j, w))
        disF = floyd(n, edges)
        disD = dijkstra_all(adj, n)
        for i in range(n):
            for j in range(n):
                a, b = disF[i][j], disD[i][j]
                if a == float('inf') or b == float('inf'):
                    assert a == b, (i, j, a, b)
                else:
                    assert a == b, (i, j, a, b)

    # 负环检测
    assert floyd_has_neg_cycle(3, [(0, 1, 1), (1, 2, -1), (2, 0, -2)]) is True
    assert floyd_has_neg_cycle(3, [(0, 1, 1), (1, 2, -1), (2, 0, 1)]) is False

    # 路径重建
    edges = [(0, 1, 2), (0, 2, 5), (1, 3, 1), (2, 3, 2), (1, 2, 1)]
    d, p = floyd_path(4, edges, 0, 3)
    assert d == 3 and p == [0, 1, 3], (d, p)
    print("All tests passed.")
